source='''def transform(grid):
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if grid[r][c] != 6:
                continue
            seen = {(r, c)}
            frontier = [(r, c)]
            replacement = None
            while frontier and replacement is None:
                x, y = frontier.pop(0)
                for a, b in ((y, x), (31 - x, y), (x, 31 - y)):
                    if 0 <= a < n and 0 <= b < m and (a, b) not in seen:
                        seen.add((a, b))
                        if grid[a][b] != 6:
                            replacement = grid[a][b]
                            break
                        frontier.append((a, b))
            if replacement is None:
                raise ValueError(f"No visible symmetric source for {(r, c)}")
            out[r][c] = replacement
    return out
'''
